<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">label</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">class</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;control-label&quot;</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">for</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;inputWarning2&quot;</span><span style="color:#24292E;">&gt;Input with warning&lt;/</span><span style="color:#22863A;">label</span><span style="color:#24292E;">&gt;</span></span>
